<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS factures_clients (id INT AUTO_INCREMENT PRIMARY KEY,bon_commande_id INT NOT NULL,numero_facture VARCHAR(100) NOT NULL,date_facture DATE NOT NULL,date_echeance DATE NOT NULL,montant_ttc DECIMAL(15,2) NOT NULL,statut VARCHAR(30) NOT NULL DEFAULT 'emise',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_invoice_order(bon_commande_id),UNIQUE KEY uniq_invoice_number(numero_facture)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
